import type { CSSProperties, ReactNode } from "react";
import { DocIcon } from "@/components/docs/icon";
import type { BrandKey } from "@/lib/docs/types";
import type { Locale } from "@/lib/i18n/dict";
import { cx } from "@/utils/cx";

/**
 * Brand specimens for the Brand docs page. Every logo is a file in public/brand (generated by sama-brand/build.mjs),
 * so what the page shows is exactly what people download.
 */

const L = (en: string, id: string) => ({ en, id });

/** Fixed brand grounds: the same in both themes, because they show how the logo looks on that colour. */
const GROUND = {
  white: "bg-white",
  mist: "bg-[#f4f4f3]",
  ink: "bg-[#1d1d1d]",
  orange: "bg-[#ff4a17]",
  sky: "bg-[#0d2f6e]",
} as const;
type Ground = keyof typeof GROUND;

type Asset = { file: string; name: { en: string; id: string }; use: { en: string; id: string }; ground: Ground; width: string };

const HORIZONTAL: Asset[] = [
  { file: "sama-logo-color.svg", name: L("Colour", "Warna"), use: L("Default, light backgrounds", "Default, latar terang"), ground: "white", width: "w-44" },
  { file: "sama-logo-color-on-dark.svg", name: L("Colour on dark", "Warna di gelap"), use: L("Dark backgrounds, dark mode", "Latar gelap, dark mode"), ground: "ink", width: "w-44" },
  { file: "sama-logo-white.svg", name: L("White", "Putih"), use: L("Orange, Sky or photos", "Oranye, Sky, atau foto"), ground: "orange", width: "w-44" },
  { file: "sama-logo-ink.svg", name: L("Black", "Hitam"), use: L("One-colour print", "Cetak satu warna"), ground: "white", width: "w-44" },
];
const STACKED: Asset[] = [
  { file: "sama-logo-stacked-color.svg", name: L("Stacked colour", "Bertumpuk warna"), use: L("Square spaces, splash", "Ruang persegi, splash"), ground: "white", width: "w-24" },
  { file: "sama-logo-stacked-white.svg", name: L("Stacked white", "Bertumpuk putih"), use: L("Business cards, dark grounds", "Kartu nama, latar gelap"), ground: "sky", width: "w-24" },
  { file: "sama-logo-stacked-ink.svg", name: L("Stacked black", "Bertumpuk hitam"), use: L("One-colour print", "Cetak satu warna"), ground: "white", width: "w-24" },
];
const MARKS: Asset[] = [
  { file: "sama-mark-orange.svg", name: L("Symbol orange", "Simbol oranye"), use: L("Favicon, watermark", "Favicon, watermark"), ground: "white", width: "w-11" },
  { file: "sama-mark-white.svg", name: L("Symbol white", "Simbol putih"), use: L("Avatars, dark grounds", "Avatar, latar gelap"), ground: "orange", width: "w-11" },
  { file: "sama-mark-ink.svg", name: L("Symbol black", "Simbol hitam"), use: L("One-colour print", "Cetak satu warna"), ground: "white", width: "w-11" },
];
const ICONS: Asset[] = [
  { file: "sama-app-icon.svg", name: L("App icon", "Ikon aplikasi"), use: L("App, PWA, favicon", "Aplikasi, PWA, favicon"), ground: "mist", width: "w-16" },
  { file: "sama-app-icon-3d.svg", name: L("Early 3D icon", "Ikon 3D versi awal"), use: L("Promotional material", "Materi promosi"), ground: "mist", width: "w-16" },
];

const src = (file: string) => `/brand/${file}`;

function Stage({ ground, className, children, style }: { ground: Ground; className?: string; children: ReactNode; style?: CSSProperties }) {
  return (
    <div className={cx("relative grid place-items-center overflow-hidden rounded-[20px] ring-1 ring-line", GROUND[ground], className)} style={style}>
      {children}
    </div>
  );
}

function Logo({ file, className, style }: { file: string; className?: string; style?: CSSProperties }) {
  // eslint-disable-next-line @next/next/no-img-element
  return <img src={src(file)} alt="" aria-hidden="true" className={cx("h-auto", className)} style={style} />;
}

function AssetCard({ a, locale }: { a: Asset; locale: Locale }) {
  return (
    <figure className="m-0 grid gap-2.5">
      <Stage ground={a.ground} className="h-36 p-6">
        <Logo file={a.file} className={a.width} />
      </Stage>
      <figcaption className="flex items-start justify-between gap-3">
        <span className="min-w-0">
          <span className="block text-sm font-semibold text-ink">{a.name[locale]}</span>
          <span className="block text-[13px] leading-5 text-ink-3">{a.use[locale]}</span>
        </span>
        <a
          href={src(a.file)}
          download
          className="inline-flex shrink-0 items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-semibold text-ink ring-1 ring-line transition-colors hover:bg-surface-2"
          aria-label={`${locale === "id" ? "Unduh" : "Download"} ${a.file}`}
        >
          <DocIcon name="download" size={14} />SVG
        </a>
      </figcaption>
    </figure>
  );
}

const COLORS: Array<{ name: string; hex: string; rgb: string; role: { en: string; id: string }; text: string }> = [
  { name: "SAMA Orange", hex: "#FF4A17", rgb: "255 74 23", role: L("Logo, highlights", "Logo, sorotan"), text: "#1D1D1D" },
  { name: "Ember", hex: "#E0230B", rgb: "224 35 11", role: L("Buttons with white text, gradients", "Tombol teks putih, gradien"), text: "#FFFFFF" },
  { name: "Flame", hex: "#FF8A4C", rgb: "255 138 76", role: L("Gradient start, illustration", "Awal gradien, ilustrasi"), text: "#1D1D1D" },
  { name: "Accent (UI)", hex: "#C8360F", rgb: "200 54 15", role: L("`--accent` in light mode", "`--accent` di mode terang"), text: "#FFFFFF" },
  { name: "Ink", hex: "#1D1D1D", rgb: "29 29 29", role: L("Wordmark, text", "Wordmark, teks"), text: "#FFFFFF" },
  { name: "Mist", hex: "#F4F4F3", rgb: "244 244 243", role: L("Soft surfaces", "Permukaan lembut"), text: "#1D1D1D" },
  { name: "Sky", hex: "#0D2F6E", rgb: "13 47 110", role: L("Dark panels, hero", "Panel gelap, hero"), text: "#FFFFFF" },
  { name: "Match", hex: "#2563D9", rgb: "37 99 217", role: L("Wallet-to-wallet transfers", "Transfer antar dompet"), text: "#FFFFFF" },
];

const MISUSE: Array<{ title: { en: string; id: string }; ground: Ground | "busy"; file: string; style: CSSProperties; className?: string }> = [
  { title: L("Stretched", "Direnggangkan"), ground: "white", file: "sama-logo-color.svg", style: { width: "11rem", height: "1rem" } },
  { title: L("Rotated", "Diputar"), ground: "white", file: "sama-logo-color.svg", style: { transform: "rotate(-14deg)" }, className: "w-36" },
  { title: L("Off-palette colour", "Warna di luar palet"), ground: "white", file: "sama-logo-color.svg", style: { filter: "hue-rotate(200deg)" }, className: "w-36" },
  { title: L("Shadows or effects", "Bayangan atau efek"), ground: "white", file: "sama-logo-color.svg", style: { filter: "drop-shadow(5px 7px 3px rgb(0 0 0 / 0.45))" }, className: "w-36" },
  { title: L("Low contrast", "Kontras rendah"), ground: "orange", file: "sama-logo-white.svg", style: { opacity: 0.35 }, className: "w-36" },
  { title: L("Busy background", "Latar ramai"), ground: "busy", file: "sama-logo-white.svg", style: {}, className: "w-36" },
];

export function BrandSpecimen({ show, locale }: { show: BrandKey; locale: Locale }) {
  switch (show) {
    case "primary":
      return (
        <div className="mt-7 grid gap-3 sm:grid-cols-2">
          <Stage ground="white" className="h-48 p-8 sm:col-span-2 sm:h-64"><Logo file="sama-logo-color.svg" className="w-64 sm:w-80" /></Stage>
          <Stage ground="ink" className="h-36 p-6"><Logo file="sama-logo-color-on-dark.svg" className="w-40" /></Stage>
          <Stage ground="orange" className="h-36 p-6"><Logo file="sama-mark-white.svg" className="w-12" /></Stage>
        </div>
      );

    case "variants":
      return (
        <div className="mt-7 grid gap-8">
          {/* Column counts match each group's size, so no card sits alone in a row. */}
          {([[HORIZONTAL, "sm:grid-cols-2"], [STACKED, "sm:grid-cols-3"], [MARKS, "sm:grid-cols-3"], [ICONS, "sm:grid-cols-2"]] as const).map(([group, cols], i) => (
            <div key={i} className={cx("grid gap-x-3 gap-y-6", cols)}>
              {group.map((a) => <AssetCard key={a.file} a={a} locale={locale} />)}
            </div>
          ))}
        </div>
      );

    case "clearspace":
      return (
        <div className="glass-panel compact-scroll mt-7 overflow-x-auto rounded-[20px] p-5 sm:p-8">
          <svg viewBox="0 0 1300 388" className="h-auto w-full min-w-[480px] text-ink" role="img" aria-label={locale === "id" ? "Ruang kosong 1x di sekeliling logo" : "1x clear space around the logo"}>
            <rect x="1" y="1" width="1298" height="386" fill="none" stroke="currentColor" strokeOpacity="0.4" strokeWidth="2" strokeDasharray="10 8" />
            <g fill="#FF4A17" fillOpacity="0.16">
              <rect x="0" y="0" width="76" height="76" /><rect x="1224" y="0" width="76" height="76" />
              <rect x="0" y="312" width="76" height="76" /><rect x="1224" y="312" width="76" height="76" />
            </g>
            <g fill="currentColor" fillOpacity="0.65" fontFamily="ui-monospace, monospace" fontSize="28" textAnchor="middle">
              <text x="38" y="47">x</text><text x="1262" y="47">x</text><text x="38" y="359">x</text><text x="1262" y="359">x</text>
            </g>
            <rect x="76" y="76" width="1148" height="236" fill="#FFFFFF" stroke="currentColor" strokeOpacity="0.18" strokeWidth="2" />
            <image href={src("sama-logo-color.svg")} x="76" y="76" width="1148" height="236" />
          </svg>
        </div>
      );

    case "sizes":
      return (
        <Stage ground="white" className="mt-7 !place-items-start p-6">
          <div className="flex flex-wrap items-end gap-8">
            {[
              { file: "sama-logo-color.svg", w: 120, h: 25, label: "120 px" },
              { file: "sama-mark-orange.svg", w: 15, h: 16, label: "16" },
              { file: "sama-mark-orange.svg", w: 22, h: 24, label: "24" },
              { file: "sama-mark-orange.svg", w: 29, h: 32, label: "32" },
              { file: "sama-app-icon.svg", w: 48, h: 48, label: "48" },
              { file: "sama-app-icon.svg", w: 64, h: 64, label: "64" },
            ].map((s, i) => (
              <figure key={i} className="m-0 grid justify-items-center gap-2">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={src(s.file)} width={s.w} height={s.h} alt="" aria-hidden="true" />
                <figcaption className="font-mono text-[11px] text-[#5e5f64]">{s.label}</figcaption>
              </figure>
            ))}
          </div>
        </Stage>
      );

    case "colors":
      return (
        <div className="mt-7 grid grid-cols-2 gap-3 lg:grid-cols-4">
          {COLORS.map((c) => (
            <div key={c.hex} className="overflow-hidden rounded-[20px] ring-1 ring-line">
              <div className="flex h-24 items-end p-3 text-sm font-semibold" style={{ background: c.hex, color: c.text }}>{c.name}</div>
              <div className="grid gap-0.5 bg-surface p-3">
                <span className="select-all font-mono text-[13px] text-ink">{c.hex}</span>
                <span className="font-mono text-[11px] text-ink-3">RGB {c.rgb}</span>
                <span className="mt-1 text-xs leading-5 text-ink-3">{c.role[locale].replace(/`/g, "")}</span>
              </div>
            </div>
          ))}
        </div>
      );

    case "type":
      return (
        <div className="mt-7 grid gap-3">
          <div className="glass-panel grid items-center gap-6 rounded-[20px] p-6 sm:grid-cols-[auto_1fr] sm:p-8">
            <span className="text-[7rem] font-bold leading-[0.85] tracking-[-0.04em] text-ink" aria-hidden="true">A<span className="text-[#ff4a17]">a</span></span>
            <div className="min-w-0">
              <p className="font-mono text-[11px] uppercase tracking-[0.14em] text-ink-3">{locale === "id" ? "Huruf utama" : "Primary typeface"}</p>
              <p className="mt-1 text-2xl font-bold text-ink">SF Pro Rounded</p>
              <p className="mt-2 break-words text-ink-3">ABCDEFGHIJKLMNOPQRSTUVWXYZ<br />abcdefghijklmnopqrstuvwxyz<br />0123456789 $ % → NVDAB SPYB</p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
            {[[300, "Light"], [400, "Regular"], [500, "Medium"], [600, "Semibold"], [700, "Bold"], [800, "Heavy"]].map(([w, n]) => (
              <div key={w} className="rounded-[16px] bg-surface-2 p-4">
                <span className="block text-3xl leading-none text-ink" style={{ fontWeight: Number(w) }}>Ag</span>
                <span className="mt-2 block text-xs text-ink-3">{n} {w}</span>
              </div>
            ))}
          </div>
        </div>
      );

    case "misuse":
      return (
        <div className="mt-7 grid grid-cols-2 gap-3 lg:grid-cols-3">
          {MISUSE.map((m, i) => (
            <figure key={i} className="m-0 grid gap-2">
              <div
                className={cx("relative grid h-32 place-items-center overflow-hidden rounded-[20px] p-5 ring-1 ring-line", m.ground !== "busy" && GROUND[m.ground])}
                style={m.ground === "busy" ? { background: "linear-gradient(120deg,#5bb3a8,#e7c35a 50%,#d96ba0)" } : undefined}
              >
                <span className="absolute right-2.5 top-2.5 grid size-6 place-items-center rounded-full bg-[#c8250a] text-white"><DocIcon name="x" size={12} /></span>
                <Logo file={m.file} className={m.className} style={m.style} />
              </div>
              <figcaption className="text-sm font-semibold text-ink">{m.title[locale]}</figcaption>
            </figure>
          ))}
        </div>
      );
  }
}
